fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    if n == 0 {
        // For empty array, return two empty arrays
        (Vec::new(), Vec::new())
    } else if n == 1 {
        // For length 1, we cannot have both parts strictly shorter than original,
        // so return the whole array as first, second empty
        (a, Vec::new())
    } else {
        // For length > 1, split into two non-empty parts both strictly shorter than n
        // Split roughly in half
        let mid = n / 2;
        let left = a[..mid].to_vec();
        let right = a[mid..].to_vec();
        (left, right)
    }
}